}

function CalendarDayButton({
  className,
  day,
  modifiers,
  locale,
  ...props
}: React.ComponentProps<typeof DayButton> & { locale?: Partial<Locale> | undefined }) {
  const inheritedLocale = React.useContext(CalendarLocaleContext);
  const effectiveLocale = locale ?? inheritedLocale;
  const isFocused = modifiers['focused'];

  const ref = React.useRef<HTMLButtonElement>(null);
  React.useEffect(
    function focusActiveDay() {
      if (isFocused) {
        ref.current?.focus();
      }
    },
    [isFocused]
  );

  return (
    <Button
      className={cn(className)}
      data-day={day.date.toLocaleDateString(effectiveLocale?.code)}
      data-range-end={modifiers['range_end']}
      data-range-middle={modifiers['range_middle']}
      data-range-start={modifiers['range_start']}
      data-selected-single={
        modifiers['selected'] && !modifiers['range_start'] && !modifiers['range_end'] && !modifiers['range_middle']
      }
      ref={ref}
      size="icon"
      variant="calendar"
      {...props}
    />
  );
}

