          <React.Fragment key={group.heading || `group-${groupIndex}`}>
            {groupIndex > 0 && <CommandSeparator />}
            <CommandGroup heading={group.heading}>
              {group.items.map((item) => (
                <CommandItem
                  disabled={item.disabled ?? false}
                  key={item.label}
