  {
    defaultVariants: {
      size: 'md',
      variant: 'primary',
    },
    variants: {
      size: {
        icon: 'size-9',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        md: 'h-9 px-4 py-2 has-[>svg]:px-3',
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
      },
      variant: {
        destructive:
          'bg-destructive text-white shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        outline:
          'border !border-border bg-background text-foreground shadow-xs hover:border-ring hover:bg-primary/10 active:border-ring active:bg-primary/15 disabled:border-border disabled:text-muted-foreground',
        primary: 'bg-secondary text-primary-foreground shadow-xs hover:bg-secondary/80',
        secondary: 'bg-primary text-primary-foreground shadow-xs hover:bg-primary/90',
      },
    },
  }
);

type CopyButtonProps = Omit<HTMLMotionProps<'button'>, 'onCopy' | 'children'> &
  VariantProps<typeof buttonVariants> & {
    content?: string;
    delay?: number;
    onCopy?: (content: string) => void;
    isCopied?: boolean;
    onCopyChange?: (isCopied: boolean) => void;
    testId?: string;
    children?: React.ReactNode;
  };

function CopyButton({
  content,
  className,
  size,
  variant,
  delay = 3000,
  onClick,
  onCopy,
  isCopied,
  onCopyChange,
  testId,
  children,
  ...props
}: CopyButtonProps) {
  const [localIsCopied, setLocalIsCopied] = React.useState(false);
  const [copyError, setCopyError] = React.useState<string>();
  const copied = isCopied ?? localIsCopied;
  const Icon = copied === true ? CheckIcon : CopyIcon;

  const handleIsCopied = (isCopiedState: boolean) => {
    if (isCopied === undefined) {
      setLocalIsCopied(isCopiedState);
    }
    onCopyChange?.(isCopiedState);
  };

  const handleCopy = (event: React.MouseEvent<HTMLButtonElement>) => {
    if (copied === true) {
      return;
    }
    if (content !== undefined && content !== '') {
      setCopyError(undefined);
      navigator.clipboard
        .writeText(content)
        .then(() => {
          handleIsCopied(true);
          setTimeout(() => handleIsCopied(false), delay);
          onCopy?.(content);
        })
        .catch((error: unknown) => {
          setCopyError(error instanceof Error ? error.message : 'Clipboard access failed.');
          handleIsCopied(false);
        });
    }
    onClick?.(event);
  };

  return (
    <>
      <motion.button
        className={cn(buttonVariants({ size, variant }), className)}
        data-slot="copy-button"
        data-testid={testId}
        onClick={handleCopy}
        type="button"
        {...props}
      >
        <AnimatePresence mode="wait">
          <motion.span
            animate={{ opacity: 1, scale: 1 }}
            data-slot="copy-button-icon"
            exit={{ opacity: 0, scale: 0.95 }}
            initial={{ opacity: 0, scale: 0.95 }}
            key={copied === true ? 'check' : 'copy'}
            transition={{ duration: 0.15 }}
          >
            <Icon />
          </motion.span>
        </AnimatePresence>
        {children}
      </motion.button>
      {copyError ? (
        <span aria-live="assertive" className="sr-only" role="alert">
          {copyError}
        </span>
      ) : null}
    </>
  );
}

export { buttonVariants, CopyButton, type CopyButtonProps };

