  placeholder?: string;
}

const EMPTY_CUSTOM_FIELDS: CustomFieldConfig[] = [];

type JSONFieldProps = {
  schema: JSONSchemaType;
  value: JSONValue;
  onChange: (value: JSONValue) => void;
  onBlur?: () => void;
  label?: string;
  maxDepth?: number;
  showPlaceholder?: boolean;
  customFields?: CustomFieldConfig[];
