  children,
  size,
  variant,
  spacing = 2,
  orientation = 'horizontal',
  testId,
  style,
  render,
  ...props
}: ShadcnToggleGroupProps) {
  const context: ToggleGroupContextProps = {
    attached: spacing === 0,
    orientation,
    position: undefined,
    registerItem: registerUnattachedItem,
    size,
    variant,
